const SS = $json.spreadsheetId;
const creds = await $credentials('Google Sheets account');

async function readSheet(name) {
  const url = 'https://sheets.googleapis.com/v4/spreadsheets/' + encodeURIComponent(SS) + '/values/' + encodeURIComponent(name) + '?majorDimension=ROWS';
  const resp = await $http.get(url, { headers: { 'Authorization': 'Bearer ' + creds.accessToken } });
  const rows = resp.data.values;
  if (!rows || rows.length < 2) return [];
  const h = rows[0];
  return rows.slice(1).map(function(r) {
    var o = {};
    h.forEach(function(c, i) { o[c] = r[i] != null ? String(r[i]) : ''; });
    return o;
  });
}

const customers = await readSheet('Customer Notes');
const jhRows = await readSheet('Job History Review');
const prRows = await readSheet('Prospects Review');

function formatDate(d) {
  if (!d) return '';
  var p = d.split(/[\\/\\-]/);
  if (p.length === 3) {
    var m = parseInt(p[0], 10), day = parseInt(p[1], 10), y = parseInt(p[2], 10);
    if (y < 100) y += 2000;
    var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
    return day + ' ' + months[m - 1] + ' ' + y;
  }
  return d;
}

function formatCurrency(v) {
  if (!v) return '';
  var n = parseFloat(String(v).replace(/[$,]/g, ''));
  if (isNaN(n)) return String(v).trim();
  return '$' + n.toFixed(2).replace(/(\\d)(?=(\\d{3})+(?!\\d))/g, '$1,');
}

function padRight(s, n) {
  s = String(s || '');
  return s.length >= n ? s.substring(0, n) : s + ' '.repeat(n - s.length);
}

var results = [];
for (var ci = 0; ci < customers.length; ci++) {
  var c = customers[ci];
  var name = (c.Customer_Name || '').trim();
  if (!name) continue;
  var nameLower = name.toLowerCase();
  var myJH = [];
  for (var i = 0; i < jhRows.length; i++) {
    if ((jhRows[i].Customer_Name || '').trim().toLowerCase() === nameLower) myJH.push(jhRows[i]);
  }
  var myPR = [];
  for (var i = 0; i < prRows.length; i++) {
    if ((prRows[i].Prospect_Name || '').trim().toLowerCase() === nameLower) myPR.push(prRows[i]);
  }
  var noteParts = [];
  if (myJH.length > 0) {
    noteParts.push('--- Job History (' + myJH.length + ' records) ---');
    for (var i = 0; i < myJH.length; i++) {
      var r = myJH[i];
      noteParts.push(padRight(formatDate(r.Job_Date), 14) + ' ' + padRight((r.Job_Type || '').substring(0, 18), 20) + ' ' + (r.Job_Details || '').substring(0, 50) + '  ' + padRight(formatCurrency(r.Price || r.Each), 12) + '  ' + (r.Invoice_Number ? 'Inv: ' + r.Invoice_Number : ''));
    }
    noteParts.push('');
  }
  if (myPR.length > 0) {
    noteParts.push('--- Prospects (' + myPR.length + ' records) ---');
    for (var i = 0; i < myPR.length; i++) {
      var r = myPR[i];
      noteParts.push(padRight(formatDate(r.Date_Added), 14) + ' ' + (r.Estimate_Information || '').substring(0, 60) + '  [' + (r.Status || '') + ']');
    }
    noteParts.push('');
  }
  noteParts.push('Source: ' + (c.Source_Table || ''));
  var now = new Date();
  var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  noteParts.push('Generated: ' + now.getDate() + ' ' + months[now.getMonth()] + ' ' + now.getFullYear() + ' ' + String(now.getHours()).padStart(2,'0') + ':' + String(now.getMinutes()).padStart(2,'0'));
  results.push({
    json: {
      Customer_Name: c.Customer_Name,
      ServiceM8_UUID: c.ServiceM8_UUID,
      Source_Table: c.Source_Table || '',
      Note_Content: noteParts.join('\\n'),
      Approval_Status: c.Approval_Status || 'Pending',
      Review_Notes: c.Review_Notes || ''
    }
  });
}

return results;
